// Only the parts that bear on ring construction / hole elimination.
indices.clear();
vertices = 0;                       // MEMBER: running base index into the flattened vertex array
if (points.empty()) return;

double x, y;
int threshold = 80;
std::size_t len = 0;

for (size_t i = 0; threshold >= 0 && i < points.size(); i++) {
    threshold -= static_cast<int>(points[i].size());
    len += points[i].size();
}

// estimate size of nodes and indices
nodes.reset(len * 3 / 2);           // arena allocator for Node
indices.reserve(len + points[0].size());

Node* outerNode = linkedList(points[0], true);      // OUTER RING: clockwise = true
if (!outerNode || outerNode->prev == outerNode->next) return;

if (points.size() > 1) outerNode = eliminateHoles(points, outerNode);

// ... z-order bbox setup (hashing = threshold < 0) ... then earcutLinked(outerNode);

using Point = typename Ring::value_type;
double sum = 0;
const std::size_t len = points.size();
std::size_t i, j;
Node* last = nullptr;

// calculate original winding order of a polygon ring
for (i = 0, j = len > 0 ? len - 1 : 0; i < len; j = i++) {
    const auto& p1 = points[i];
    const auto& p2 = points[j];
    const double p20 = util::nth<0, Point>::get(p2);   // p2.x
    const double p10 = util::nth<0, Point>::get(p1);   // p1.x
    const double p11 = util::nth<1, Point>::get(p1);   // p1.y
    const double p21 = util::nth<1, Point>::get(p2);   // p2.y
    sum += (p20 - p10) * (p11 + p21);                  // (p2.x - p1.x) * (p1.y + p2.y)
}

// link points into circular doubly-linked list in the specified winding order
if (clockwise == (sum > 0)) {
    for (i = 0; i < len; i++)   last = insertNode(vertices + i, points[i], last);
} else {
    for (i = len; i-- > 0;)     last = insertNode(vertices + i, points[i], last);
}

if (last && equals(last, last->next)) {
    removeNode(last);
    last = last->next;
}

vertices += len;

return last;   // may be nullptr when len == 0

Node* p = nodes.construct(static_cast<N>(i),
                          util::nth<0, Point>::get(pt),
                          util::nth<1, Point>::get(pt));

if (!last) {
    p->prev = p;
    p->next = p;
} else {
    assert(last);
    p->next = last->next;
    p->prev = last;
    last->next->prev = p;
    last->next = p;
}
return p;

p->next->prev = p->prev;
p->prev->next = p->next;

if (p->prevZ) p->prevZ->nextZ = p->nextZ;
if (p->nextZ) p->nextZ->prevZ = p->prevZ;

// ===== NEWER (earcut.hpp 2.2.0 .. 2.2.4) — VARIANT (A) =====
const size_t len = points.size();

std::vector<Node*> queue;
for (size_t i = 1; i < len; i++) {                 // NOTE: starts at 1, ring 0 is the outer ring
    Node* list = linkedList(points[i], false);      // clockwise = false for holes
    if (list) {
        if (list == list->next) list->steiner = true;   // single-vertex hole => Steiner point
        queue.push_back(getLeftmost(list));
    }
}

std::sort(queue.begin(), queue.end(), [](const Node* a, const Node* b) {
    return a->x < b->x;
});

// process holes from left to right
for (size_t i = 0; i < queue.size(); i++) {
    outerNode = eliminateHole(queue[i], outerNode);
}

return outerNode;


// ===== OLDER (earcut.hpp <= 2.1.5) — VARIANT (B) =====
// identical through the std::sort, then:
for (size_t i = 0; i < queue.size(); i++) {
    eliminateHole(queue[i], outerNode);                       // returns void
    outerNode = filterPoints(outerNode, outerNode->next);
}
return outerNode;

// ===== V3: earcut.hpp 2.2.3 / 2.2.4 (and earcut.js 3.x). THIS IS THE PRIMARY TARGET. =====
Node* bridge = findHoleBridge(hole, outerNode);
if (!bridge) {
    return outerNode;
}

Node* bridgeReverse = splitPolygon(bridge, hole);

// filter collinear points around the cuts
filterPoints(bridgeReverse, bridgeReverse->next);

// Check if input node was removed by the filtering
return filterPoints(bridge, bridge->next);


// ===== V2: earcut.hpp/js 2.2.0 .. 2.2.2 =====
Node* bridge = findHoleBridge(hole, outerNode);
if (!bridge) {
    return outerNode;
}
Node* bridgeReverse = splitPolygon(bridge, hole);
// filter collinear points around the cuts
Node* filteredBridge = filterPoints(bridge, bridge->next);
filterPoints(bridgeReverse, bridgeReverse->next);
// Check if input node was removed by the filtering
return outerNode == bridge ? filteredBridge : outerNode;


// ===== V1: earcut.hpp/js <= 2.1.5 (returns void) =====
outerNode = findHoleBridge(hole, outerNode);     // shadows the by-value parameter
if (outerNode) {
    Node* b = splitPolygon(outerNode, hole);
    filterPoints(b, b->next);
}
// no return; caller does outerNode = filterPoints(outerNode, outerNode->next);

// ===== NEWER (earcut.hpp 2.2.0 .. 2.2.4). David Eberly's algorithm. =====
Node* p = outerNode;
double hx = hole->x;
double hy = hole->y;
double qx = -std::numeric_limits<double>::infinity();
Node* m = nullptr;

// find a segment intersected by a ray from the hole's leftmost Vertex to the left;
// segment's endpoint with lesser x will be potential connection Vertex
do {
    if (hy <= p->y && hy >= p->next->y && p->next->y != p->y) {
        double x = p->x + (hy - p->y) * (p->next->x - p->x) / (p->next->y - p->y);
        if (x <= hx && x > qx) {
            qx = x;
            m = p->x < p->next->x ? p : p->next;
            if (x == hx) return m;   // hole touches outer segment; pick leftmost endpoint
        }
    }
    p = p->next;
} while (p != outerNode);

if (!m) return 0;

// look for points inside the triangle of hole Vertex, segment intersection and endpoint;
// if there are no points found, we have a valid connection;
// otherwise choose the Vertex of the minimum angle with the ray as connection Vertex

const Node* stop = m;
double tanMin = std::numeric_limits<double>::infinity();

p = m;                       // <-- NEWER starts AT m (do/while, so m itself is tested)
double mx = m->x;
double my = m->y;

do {
    if (hx >= p->x && p->x >= mx && hx != p->x &&
        pointInTriangle(hy < my ? hx : qx, hy,
                        mx, my,
                        hy < my ? qx : hx, hy,
                        p->x, p->y)) {

        double tan = std::abs(hy - p->y) / (hx - p->x);   // tangential

        if (locallyInside(p, hole) &&
            (tan < tanMin || (tan == tanMin && (p->x > m->x || sectorContainsSector(m, p))))) {
            m = p;
            tanMin = tan;
        }
    }

    p = p->next;
} while (p != stop);

return m;


// ===== OLDER (earcut.hpp <= 2.1.5) =====
Node* p = outerNode;
double hx = hole->x, hy = hole->y;
double qx = -std::numeric_limits<double>::infinity();
Node* m = nullptr;

do {
    if (hy <= p->y && hy >= p->next->y && p->next->y != p->y) {
        double x = p->x + (hy - p->y) * (p->next->x - p->x) / (p->next->y - p->y);
        if (x <= hx && x > qx) {
            qx = x;
            if (x == hx) {
                if (hy == p->y)       return p;
                if (hy == p->next->y) return p->next;
            }
            m = p->x < p->next->x ? p : p->next;
        }
    }
    p = p->next;
} while (p != outerNode);

if (!m) return 0;

if (hx == qx) return m->prev;   // hole touches outer segment; pick lower endpoint

const Node* stop = m;
double tanMin = std::numeric_limits<double>::infinity();
double mx = m->x, my = m->y;

p = m->next;                    // <-- OLDER starts at m->next (while loop; m itself NOT tested)
while (p != stop) {
    if (hx >= p->x && p->x >= mx && hx != p->x &&
        pointInTriangle(hy < my ? hx : qx, hy, mx, my, hy < my ? qx : hx, hy, p->x, p->y)) {

        double tan = std::abs(hy - p->y) / (hx - p->x);

        if ((tan < tanMin || (tan == tanMin && p->x > m->x)) && locallyInside(p, hole)) {
            m = p;
            tanMin = tan;
        }
    }
    p = p->next;
}
return m;

Node* p = start;
Node* leftmost = start;
do {
    if (p->x < leftmost->x || (p->x == leftmost->x && p->y < leftmost->y))
        leftmost = p;
    p = p->next;
} while (p != start);

return leftmost;

// link two polygon vertices with a bridge; if the vertices belong to the same ring, it splits
// the polygon into two; if one belongs to the outer ring and another to a hole, it merges them
// into a single ring
Node* a2 = nodes.construct(a->i, a->x, a->y);
Node* b2 = nodes.construct(b->i, b->x, b->y);
Node* an = a->next;
Node* bp = b->prev;

a->next = b;
b->prev = a;

a2->next = an;
an->prev = a2;

b2->next = a2;
a2->prev = b2;

bp->next = b2;
b2->prev = bp;

return b2;

if (!start) return start;      // present in some revisions; 2.2.4 body begins with the `if (!end)` line
if (!end) end = start;

Node* p = start;
bool again;
do {
    again = false;

    if (!p->steiner && (equals(p, p->next) || area(p->prev, p, p->next) == 0)) {
        removeNode(p);
        p = end = p->prev;

        if (p == p->next) break;
        again = true;
    } else {
        p = p->next;
    }
} while (again || p != end);

return end;

bool equals(const Node* p1, const Node* p2) {
    return p1->x == p2->x && p1->y == p2->y;
}

// signed area of a triangle
double area(const Node* p, const Node* q, const Node* r) const {
    return (q->y - p->y) * (r->x - q->x) - (q->x - p->x) * (r->y - q->y);
}

// check if a point lies within a convex triangle
bool pointInTriangle(double ax, double ay, double bx, double by,
                     double cx, double cy, double px, double py) const {
    return (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0 &&
           (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0 &&
           (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0;
}

// check if a polygon diagonal is locally inside the polygon
bool locallyInside(const Node* a, const Node* b) {
    return area(a->prev, a, a->next) < 0 ?
        area(a, b, a->next) >= 0 && area(a, a->prev, b) >= 0 :
        area(a, b, a->prev) < 0 || area(a, a->next, b) < 0;
}
